package com.univmar.admin;
import com.univmar.admin.api.AdminDtos; import com.univmar.audit.domain.AuditEventRepository; import com.univmar.shared.api.ApiException; import com.univmar.user.domain.User; import com.univmar.user.domain.UserRepository; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AdminService {private final UserRepository users;private final AuditEventRepository events;public AdminService(UserRepository users,AuditEventRepository events){this.users=users;this.events=events;}@Transactional(readOnly=true) public List<AdminDtos.UserResponse> users(){return users.findAll().stream().map(this::user).toList();}@Transactional public AdminDtos.UserResponse updateUser(Long id,AdminDtos.UserUpdate input){User user=users.findById(id).orElseThrow(()->ApiException.notFound("User"));user.changeRole(input.role());if(input.active())user.enable();else user.disable();return user(user);}@Transactional(readOnly=true) public List<AdminDtos.AuditResponse> audit(String type,Long id){return events.findTop100ByEntityTypeAndEntityIdOrderByCreatedAtDesc(type,id).stream().map(x->new AdminDtos.AuditResponse(x.getId(),x.getActorId(),x.getAction(),x.getEntityType(),x.getEntityId(),x.getDetail(),x.getCreatedAt())).toList();}private AdminDtos.UserResponse user(User x){return new AdminDtos.UserResponse(x.getId(),x.getEmail(),x.getRole().name(),x.getStatus().name(),x.getCreatedAt());}}
